    paren_string = paren_string.replace(" ", "")

    def is_balanced(s: str) -> bool:
        stack = []
        for char in s:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack or stack[-1] != '(':
                    return False
                stack.pop()
        return not stack

    def separate_groups(s: str) -> List[str]:
        groups = []
        start = 0
        count = 0
        for i, char in enumerate(s):
            if char == '(':
                count += 1
            elif char == ')':
                count -= 1
            if count == 0:
                groups.append(s[start:i+1])
                start = i + 1
        return groups

    result = []
    groups = separate_groups(paren_string)
    for group in groups:
        if is_balanced(group):
            result.append(group)

    return result

