from typing import List

def rolling_max(numbers: List[int], k: int) -> List[int]:
    if not numbers or k <= 0:
        return []

    rolling_max_list = []
    window = []

    for i in range(len(numbers)):
        if i >= k and window[0] == numbers[i - k]:
            window.pop(0)

        while window and numbers[i] > window[-1]:
            window.pop()

        window.append(numbers[i])

        if i >= k - 1:
            rolling_max_list.append(window[0])

    return rolling_max_list

