from typing import List

def rolling_max(numbers: List[int]) -> List[int]:
    if not numbers:
        return []

    k = 1
    rolling_maxs = []
    window = []

    for i, num in enumerate(numbers):
        if i >= k:
            window.pop(0)

        while window and window[-1] < num:
            window.pop()

        window.append(num)

        if i >= k - 1:
            rolling_maxs.append(window[0])

    return rolling_maxs

